func (s richSubset) JSONSize() int {
	size := 391
	size += s.Big.BitLen() / 3
	size += (s.BigR.Num().BitLen() + s.BigR.Denom().BitLen()) / 3
	if n := len(s.Raw1); n > 0 {
		size += n
	} else {
		size += 4
	}
	if n := len(s.Raw2); n > 0 {
		size += n
	} else {
		size += 4
	}
	return size
}

func (s richSubset) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"big\":"...)
	dst = (&s.Big).Append(dst, 10)
	dst = append(dst, ",\"bigF\":\""...)
	dst = (&s.BigF).Append(dst, 'g', -1)
	dst = append(dst, "\",\"bigR\":\""...)
	if dst, err = (&s.BigR).AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"gofrsId\":"...)
	{
		var t []byte
		t, err = s.GofrsID.MarshalText()
		if err != nil {
			return dst, err
		}
		dst = append(dst, '"')
		dst = encode.AppendStringNoHTML(dst, encode.BytesToString(t))
	}
	dst = append(dst, ",\"id\":"...)
	{
		var t []byte
		t, err = s.ID.MarshalText()
		if err != nil {
			return dst, err
		}
		dst = append(dst, '"')
		dst = encode.AppendStringNoHTML(dst, encode.BytesToString(t))
	}
	dst = append(dst, ",\"raw1\":"...)
	if len(s.Raw1) == 0 {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, s.Raw1...)
	}
	dst = append(dst, ",\"raw2\":"...)
	if len(s.Raw2) == 0 {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, s.Raw2...)
	}
	return append(dst, '}'), nil
}

